        const state = {
            concept: "How to maximize daily efficiency",
            beats: [
                { visual: "Tight zoom on a ticking watch face, looking frustrated.", dialogue: "Stop wasting hours rewriting your daily content workflow.", duration: 3 },
                { visual: "Quick cuts of messy desktop folders and notes applications open simultaneously.", dialogue: "Most creators lose half their day simply planning what to shoot next.", duration: 12 },
