                { visual: "Direct to camera view pointing downward toward caption link location.", dialogue: "Drop a comment below to grab this direct template file for yourself.", duration: 5 }
            ]
        };

        const conceptInput = document.getElementById('concept');
        const beatsContainer = document.getElementById('beats-container');
        const cardsContainer = document.getElementById('cards-container');
        const warningsDiv = document.getElementById('warnings');
        const totalTimeClock = document.getElementById('total-time');
        const hookTimeClock = document.getElementById('hook-time');

