            conceptInput.value = state.concept;
            conceptInput.addEventListener('input', (e) => {
                state.concept = e.target.value;
            });

            btnAdd.addEventListener('click', addBeat);
            btnCopy.addEventListener('click', copyToClipboard);
            btnDownload.addEventListener('click', downloadConfig);

            renderBeats();
        }

        function renderBeats() {
            while (beatsContainer.firstChild) {
                beatsContainer.removeChild(beatsContainer.firstChild);
            }

            state.beats.forEach((beat, index) => {
                const beatItem = document.createElement('div');
                beatItem.setAttribute('class', 'beat-item');

                const beatHeader = document.createElement('div');
                beatHeader.setAttribute('class', 'beat-header');

                const beatTitle = document.createElement('span');
                beatTitle.setAttribute('class', 'beat-title');
                beatTitle.textContent = index === 0 ? '#1: Hook Scene' : `#${index + 1}: Beat Card`;
