                const durationCtrl = document.createElement('div');
                durationCtrl.setAttribute('class', 'duration-ctrl');

                const durationLabel = document.createElement('label');
                durationLabel.textContent = 'Secs:';
                durationCtrl.appendChild(durationLabel);

                const durationInput = document.createElement('input');
                durationInput.setAttribute('type', 'number');
                durationInput.setAttribute('min', '1');
                durationInput.setAttribute('max', '60');
