        }

        function buildAllCards() {
            while (cardsContainer.firstChild) {
                cardsContainer.removeChild(cardsContainer.firstChild);
            }

            state.beats.forEach((_, index) => {
                const card = document.createElement('div');
                card.setAttribute('class', 'shot-card');

                const metaDiv = document.createElement('div');
                metaDiv.setAttribute('class', 'shot-meta');

                const metaLeft = document.createElement('span');
                const metaRight = document.createElement('span');
                metaDiv.appendChild(metaLeft);
                metaDiv.appendChild(metaRight);
                card.appendChild(metaDiv);

                const bodyDiv = document.createElement('div');
                bodyDiv.setAttribute('class', 'shot-body');

                const visualElem = document.createElement('div');
                visualElem.setAttribute('class', 'shot-element');
                const visualSpan = document.createElement('span');
                visualSpan.textContent = 'Visual/Frame';
                const visualText = document.createElement('div');
                visualElem.appendChild(visualSpan);
                visualElem.appendChild(visualText);
                bodyDiv.appendChild(visualElem);

                const dialogueElem = document.createElement('div');
                dialogueElem.setAttribute('class', 'shot-element');
                dialogueElem.style.margin = '0';
                const dialogueSpan = document.createElement('span');
                dialogueSpan.textContent = 'Dialogue/Audio';
                const dialogueText = document.createElement('div');
                dialogueElem.appendChild(dialogueSpan);
                dialogueElem.appendChild(dialogueText);
                bodyDiv.appendChild(dialogueElem);

                card.appendChild(bodyDiv);
                cardsContainer.appendChild(card);

                updateCardDOM(index, card);
            });
        }

        function updateSingleCard(index) {
            const card = cardsContainer.children[index];
            if (card) {
                updateCardDOM(index, card);
            }
        }

        function updateCardDOM(index, cardDiv) {
            const beat = state.beats[index];

            let startTime = 0;
            for (let i = 0; i < index; i++) {
                startTime += state.beats[i].duration;
            }
            const endTime = startTime + beat.duration;

            const metaDiv = cardDiv.children[0];
            metaDiv.children[0].textContent = `Card #${index + 1} (${beat.duration}s)`;
            metaDiv.children[1].textContent = `${startTime}s - ${endTime}s`;

            const bodyDiv = cardDiv.children[1];

            const visualTextDiv = bodyDiv.children[0].children[1];
            if (beat.visual.trim() === '') {
                visualTextDiv.textContent = 'No details';
                visualTextDiv.setAttribute('class', 'placeholder-text');
            } else {
                visualTextDiv.textContent = beat.visual;
                visualTextDiv.removeAttribute('class');
            }

            const dialogueTextDiv = bodyDiv.children[1].children[1];
            if (beat.dialogue.trim() === '') {
                dialogueTextDiv.textContent = 'Silence';
                dialogueTextDiv.setAttribute('class', 'placeholder-text');
            } else {
                dialogueTextDiv.textContent = beat.dialogue;
                dialogueTextDiv.removeAttribute('class');
            }
        }

        function calculateTiming() {
            let totalSecs = 0;
            const hookSecs = state.beats[0] ? state.beats[0].duration : 0;

            state.beats.forEach(b => totalSecs += b.duration);

            totalTimeClock.textContent = `${totalSecs}s`;
            hookTimeClock.textContent = `${hookSecs}s`;

            let warningMessages = [];

            if (hookSecs > 3) {
                warningMessages.push(`⚠️ Slow Opening: Hook duration (${hookSecs}s) exceeds the optimal 3-second short-form attention window.`);
                hookTimeClock.style.color = 'var(--warning)';
            } else {
                hookTimeClock.style.color = 'var(--success)';
            }

            if (totalSecs < 30 || totalSecs > 60) {
                warningMessages.push(`⚠️ Pacing Notice: Total runtime (${totalSecs}s) is outside the requested 30-60 second structural threshold.`);
                totalTimeClock.style.color = 'var(--warning)';
            } else {
                totalTimeClock.style.color = 'var(--success)';
            }

            if (warningMessages.length > 0) {
                warningsDiv.textContent = warningMessages.join('\n\n');
                warningsDiv.style.display = 'block';
            } else {
                warningsDiv.textContent = '';
                warningsDiv.style.display = 'none';
            }

            state.beats.forEach((_, index) => updateSingleCard(index));
        }

        function generateScriptOutput() {
            let output = `CONCEPT: ${state.concept}\n\n`;
            let runningTime = 0;
            state.beats.forEach((b, i) => {
                output += `[${runningTime}s - ${runningTime + b.duration}s] Beat #${i+1}\n`;
                output += `VISUAL: ${b.visual}\n`;
                output += `AUDIO:  ${b.dialogue}\n\n`;
                runningTime += b.duration;
            });
            return output;
        }

        function copyToClipboard() {
            const text = generateScriptOutput();
            navigator.clipboard.writeText(text).then(() => {
                alert("Script copied cleanly to clipboard!");
            }).catch(err => {
                alert("Error copying content: " + err);
            });
        }

        function downloadConfig() {
            const fileData = {
                timestamp: new Date().toISOString(),
                data: state
            };
            const blob = new Blob([JSON.stringify(fileData, null, 2)], { type: "application/json" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.setAttribute('href', url);

            const sanitizedConcept = state.concept.toLowerCase().replace(/[^a-z0-9]+/g, '-');
            a.setAttribute('download', `video-plan-${sanitizedConcept || 'untitled'}.json`);

            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }

        window.onload = init;
    </script>
</body>
</html>
